import { describe, it, expect, beforeEach, vi } from "vitest";
import {
  encrypt,
  decrypt,
  reencryptToActive,
  extractKeyId,
  getActiveKeyId,
  _resetCryptoCacheForTests,
} from "../crypto";

const KEY_V1 =
  "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";
const KEY_V2 =
  "fedcba9876543210fedcba9876543210fedcba9876543210fedcba9876543210";

describe("crypto (AES-256-GCM, key versioning)", () => {
  beforeEach(() => {
    vi.unstubAllEnvs();
    vi.stubEnv("ENCRYPTION_KEYS", "");
    vi.stubEnv("ENCRYPTION_ACTIVE_KEY_ID", "");
    vi.stubEnv("ENCRYPTION_KEY", KEY_V1);
    _resetCryptoCacheForTests();
  });

  it("encrypts and decrypts back to original (legacy single-key path)", () => {
    const plaintext = "my-secret-access-token-12345";
    const encrypted = encrypt(plaintext);
    expect(encrypted).not.toBe(plaintext);
    expect(decrypt(encrypted)).toBe(plaintext);
  });

  it("uses the synthetic 'v1' id when only ENCRYPTION_KEY is set", () => {
    expect(getActiveKeyId()).toBe("v1");
    const encrypted = encrypt("hello");
    expect(encrypted.startsWith("v1.")).toBe(true);
    expect(extractKeyId(encrypted)).toBe("v1");
  });

  it("produces different ciphertext each time (random IV)", () => {
    const a = encrypt("same-input");
    const b = encrypt("same-input");
    expect(a).not.toBe(b);
    expect(decrypt(a)).toBe("same-input");
    expect(decrypt(b)).toBe("same-input");
  });

  it("handles empty strings, unicode, long input", () => {
    expect(decrypt(encrypt(""))).toBe("");
    expect(decrypt(encrypt("Zugangsdaten: 🔐 € ñ"))).toBe(
      "Zugangsdaten: 🔐 € ñ",
    );
    expect(decrypt(encrypt("x".repeat(10000)))).toBe("x".repeat(10000));
  });

  it("decrypts legacy unversioned ciphertext (bare base64)", () => {
    // Manually craft a legacy bare-base64 encryption with KEY_V1 by stripping
    // the v1. prefix the new encoder adds.
    const versioned = encrypt("legacy-row");
    const legacy = versioned.slice("v1.".length);
    // legacy should still decrypt because v1 key is in the keymap
    expect(decrypt(legacy)).toBe("legacy-row");
  });

  it("supports ENCRYPTION_KEYS + ENCRYPTION_ACTIVE_KEY_ID multi-key mode", () => {
    vi.stubEnv("ENCRYPTION_KEYS", JSON.stringify({ v1: KEY_V1, v2: KEY_V2 }));
    vi.stubEnv("ENCRYPTION_ACTIVE_KEY_ID", "v2");
    vi.stubEnv("ENCRYPTION_KEY", "");
    _resetCryptoCacheForTests();

    expect(getActiveKeyId()).toBe("v2");
    const ct = encrypt("multi-key-secret");
    expect(ct.startsWith("v2.")).toBe(true);
    expect(decrypt(ct)).toBe("multi-key-secret");
  });

  it("rotation: rows encrypted under old key still decrypt after switching active id", () => {
    // Write under v1
    vi.stubEnv("ENCRYPTION_KEYS", JSON.stringify({ v1: KEY_V1 }));
    vi.stubEnv("ENCRYPTION_ACTIVE_KEY_ID", "v1");
    vi.stubEnv("ENCRYPTION_KEY", "");
    _resetCryptoCacheForTests();
    const oldRow = encrypt("rotate-me");
    expect(oldRow.startsWith("v1.")).toBe(true);

    // Add v2 and rotate active to v2; old row still decrypts
    vi.stubEnv("ENCRYPTION_KEYS", JSON.stringify({ v1: KEY_V1, v2: KEY_V2 }));
    vi.stubEnv("ENCRYPTION_ACTIVE_KEY_ID", "v2");
    _resetCryptoCacheForTests();
    expect(decrypt(oldRow)).toBe("rotate-me");

    const newRow = reencryptToActive(oldRow);
    expect(newRow.startsWith("v2.")).toBe(true);
    expect(decrypt(newRow)).toBe("rotate-me");
  });

  it("fails to decrypt with wrong key", () => {
    const encrypted = encrypt("secret");
    vi.stubEnv("ENCRYPTION_KEY", "f".repeat(64));
    _resetCryptoCacheForTests();
    expect(() => decrypt(encrypted)).toThrow();
  });

  it("fails to decrypt tampered ciphertext", () => {
    const encrypted = encrypt("secret");
    // Versioned: "v1.<base64>"
    const dot = encrypted.indexOf(".");
    const buf = Buffer.from(encrypted.slice(dot + 1), "base64");
    buf[buf.length - 1] ^= 0xff;
    const tampered = `v1.${buf.toString("base64")}`;
    expect(() => decrypt(tampered)).toThrow();
  });

  it("throws if no encryption configuration is present", () => {
    vi.stubEnv("ENCRYPTION_KEY", "");
    vi.stubEnv("ENCRYPTION_KEYS", "");
    _resetCryptoCacheForTests();
    expect(() => encrypt("test")).toThrow(/Encryption is not configured/);
  });

  it("rejects malformed ENCRYPTION_KEYS JSON", () => {
    vi.stubEnv("ENCRYPTION_KEYS", "not-json");
    vi.stubEnv("ENCRYPTION_ACTIVE_KEY_ID", "v1");
    vi.stubEnv("ENCRYPTION_KEY", "");
    _resetCryptoCacheForTests();
    expect(() => encrypt("test")).toThrow(/valid JSON/);
  });

  it("rejects an active key id that doesn't exist in the map", () => {
    vi.stubEnv("ENCRYPTION_KEYS", JSON.stringify({ v1: KEY_V1 }));
    vi.stubEnv("ENCRYPTION_ACTIVE_KEY_ID", "v9");
    vi.stubEnv("ENCRYPTION_KEY", "");
    _resetCryptoCacheForTests();
    expect(() => encrypt("test")).toThrow(/no matching entry/);
  });

  // A 40-char hex string is too short for a 256-bit key but long enough to
  // reach the dev-only SHA-256 padding branch (base64-decodes to 30 bytes, so
  // it falls through to the >=32-hex path). It must only pad in development /
  // test and otherwise fail closed.
  const SHORT_HEX_KEY = "0123456789abcdef0123456789abcdef01234567";

  it("fails closed when NODE_ENV is unset and only a short hex key is set", () => {
    vi.stubEnv("NODE_ENV", undefined);
    vi.stubEnv("ENCRYPTION_KEYS", "");
    vi.stubEnv("ENCRYPTION_ACTIVE_KEY_ID", "");
    vi.stubEnv("ENCRYPTION_KEY", SHORT_HEX_KEY);
    _resetCryptoCacheForTests();
    expect(() => encrypt("test")).toThrow(
      /must be 64 hex characters .* outside development\/test/,
    );
  });

  it("fails closed for a short hex key in production", () => {
    vi.stubEnv("NODE_ENV", "production");
    vi.stubEnv("ENCRYPTION_KEYS", "");
    vi.stubEnv("ENCRYPTION_ACTIVE_KEY_ID", "");
    vi.stubEnv("ENCRYPTION_KEY", SHORT_HEX_KEY);
    _resetCryptoCacheForTests();
    expect(() => encrypt("test")).toThrow(/outside development\/test/);
  });

  it("still pads a short hex key in development/test for local use", () => {
    vi.stubEnv("NODE_ENV", "development");
    vi.stubEnv("ENCRYPTION_KEYS", "");
    vi.stubEnv("ENCRYPTION_ACTIVE_KEY_ID", "");
    vi.stubEnv("ENCRYPTION_KEY", SHORT_HEX_KEY);
    _resetCryptoCacheForTests();
    const ct = encrypt("dev-secret");
    expect(decrypt(ct)).toBe("dev-secret");
  });
});

src/lib/measurements/__tests__/units.pro.source:
/**
 * Unit conversions against their round-trip laws.
 *
 * What a person sees: they type a number in their own unit, it is stored in
 * the canonical one, and the screen shows it back. The number shown must be
 * the number typed, for every value they can type, in every unit the app
 * offers. And a stored value shown in another unit must not wander by more
 * than the display grain.
 */
import fc from "fast-check";
import { describe, expect, it } from "vitest";

import {
  applyDisplayTransform,
  applyDisplayTransformDelta,
  applyDisplayTransformUnrounded,
  getDisplayTransform,
  getReadingTransform,
  invertDisplayTransform,
  TRANSFORMED_TYPES,
  type UnitPreference,
} from "@/lib/measurements/display-transform";
import {
  convertGlucose,
  mgdlToMmol,
  mmolToMgdl,
  toCanonicalMgdl,
} from "@/lib/glucose";

import { assertProperty } from "../../../../tests/property/fast-check";

const typeArb = fc.constantFrom(...[...TRANSFORMED_TYPES].sort());
const preferenceArb = fc.constantFrom<UnitPreference>("metric", "imperial");
const canonicalArb = fc.double({
  min: -100,
  max: 50_000,
  noNaN: true,
  noDefaultInfinity: true,
});

/** How the entry surfaces store a typed value: two decimals, canonical unit. */
function storeTyped(display: number, type: string, pref: UnitPreference) {
  const raw = invertDisplayTransform(display, getDisplayTransform(type, pref));
  return Math.round(raw * 100) / 100;
}

describe("metric and imperial display", () => {
  it("inverts the unrounded transform exactly", () => {
    assertProperty(
      fc.property(typeArb, preferenceArb, canonicalArb, (type, pref, raw) => {
        const t = getDisplayTransform(type, pref);
        const back = invertDisplayTransform(
          applyDisplayTransformUnrounded(raw, t),
          t,
        );
        expect(Math.abs(back - raw)).toBeLessThanOrEqual(
          1e-9 * Math.max(1, Math.abs(raw)),
        );
      }),
      400,
    );
  });

  it("rounds a displayed value to within half a display step", () => {
    assertProperty(
      fc.property(typeArb, preferenceArb, canonicalArb, (type, pref, raw) => {
        const t = getDisplayTransform(type, pref);
        const shown = applyDisplayTransform(raw, t);
        const exact = applyDisplayTransformUnrounded(raw, t);
        const step = 10 ** -t.decimals;
        expect(Math.abs(shown - exact)).toBeLessThanOrEqual(step / 2 + 1e-9);
      }),
      400,
    );
  });

  it("shows back exactly the value a person typed in their own unit", () => {
    assertProperty(
      fc.property(
        typeArb,
        preferenceArb,
        fc.integer({ min: 0, max: 50_000 }),
        (type, pref, steps) => {
          const t = getDisplayTransform(type, pref);
          // A value on the display grain, as a person types it.
          const typed = steps / 10 ** t.decimals;
          const stored = storeTyped(typed, type, pref);
          expect(applyDisplayTransform(stored, t)).toBe(typed);
        },
      ),
      400,
    );
  });

  it("converts a difference by the factor alone, never the offset", () => {
    assertProperty(
      fc.property(
        typeArb,
        preferenceArb,
        canonicalArb,
        canonicalArb,
        (type, pref, a, b) => {
          const t = getDisplayTransform(type, pref);
          const viaValues =
            applyDisplayTransformUnrounded(a, t) -
            applyDisplayTransformUnrounded(b, t);
          const step = 10 ** -t.decimals;
          expect(
            Math.abs(applyDisplayTransformDelta(a - b, t) - viaValues),
          ).toBeLessThanOrEqual(
            step / 2 + 1e-6 * Math.max(1, Math.abs(viaValues)),
          );
        },
      ),
    );
  });
});

describe("blood glucose", () => {
  it("shows back exactly the mmol/L value a person typed", () => {
    assertProperty(
      fc.property(fc.integer({ min: 10, max: 400 }), (tenths) => {
        const typed = tenths / 10;
        const stored = toCanonicalMgdl(typed, "mmol/L");
        expect(Number.isInteger(stored)).toBe(true);
        expect(mgdlToMmol(stored)).toBe(typed);
        expect(convertGlucose(stored, "mmol/L")).toBe(typed);
        expect(mmolToMgdl(typed)).toBe(stored);
      }),
    );
  });

  it("moves a stored mg/dL value by at most 1 through a mmol/L round trip", () => {
    assertProperty(
      fc.property(fc.integer({ min: 18, max: 720 }), (mgdl) => {
        expect(
          Math.abs(mmolToMgdl(mgdlToMmol(mgdl)) - mgdl),
        ).toBeLessThanOrEqual(1);
      }),
    );
  });

  it("prints the same figure through the reading transform as through convertGlucose", () => {
    assertProperty(
      fc.property(fc.integer({ min: 18, max: 720 }), (mgdl) => {
        const t = getReadingTransform("BLOOD_GLUCOSE", {
          system: "metric",
          glucoseUnit: "mmol/L",
        });
        expect(applyDisplayTransform(mgdl, t)).toBe(
          convertGlucose(mgdl, "mmol/L"),
        );
      }),
    );
  });

  it("keeps mg/dL canonical: typing mg/dL stores the whole number typed", () => {
    assertProperty(
      fc.property(fc.integer({ min: 18, max: 720 }), (mgdl) => {
        expect(toCanonicalMgdl(mgdl, "mg/dL")).toBe(mgdl);
        expect(convertGlucose(mgdl, "mg/dL")).toBe(mgdl);
      }),
    );
  });
});

src/lib/rollups/__tests__/collapse-rollu.source:
/**
 * v1.11.1 — source-aware rollup collapse.
 *
 * The writer mints one rollup row per (type, day, source). This helper
 * resolves overlapping sources to ONE row per bucket via the user's
 * source-priority ladder, so a day with WHOOP + Apple Watch resting heart
 * rate surfaces the ladder-canonical reading instead of an AVG blend.
 *
 * Default ladders pinned here (from `DEFAULT_SOURCE_PRIORITY`):
 *   restingHeartRate: WHOOP > APPLE_HEALTH > WITHINGS
 *   spo2:             WITHINGS > WHOOP > APPLE_HEALTH > MANUAL
 *   recovery:         WHOOP > COMPUTED
 *   steps:            APPLE_HEALTH > WITHINGS > MANUAL
 */
import { describe, expect, it } from "vitest";

import type { MeasurementSource } from "@/generated/prisma/client";
import { collapseRollupRowsBySource } from "../measurement-read";

interface Row {
  bucketStart: Date;
  source: MeasurementSource;
  count: number;
  mean: number;
  sumValue: number | null;
}

const DAY1 = new Date("2026-06-01T00:00:00.000Z");
const DAY2 = new Date("2026-06-02T00:00:00.000Z");

function row(
  bucketStart: Date,
  source: MeasurementSource,
  mean: number,
  count = 1,
  sumValue: number | null = null,
): Row {
  return { bucketStart, source, count, mean, sumValue };
}

describe("collapseRollupRowsBySource", () => {
  it("picks WHOOP over Apple for resting heart rate (ladder head wins)", () => {
    const out = collapseRollupRowsBySource(
      [row(DAY1, "APPLE_HEALTH", 54), row(DAY1, "WHOOP", 51)],
      "RESTING_HEART_RATE",
      null,
    );
    expect(out).toHaveLength(1);
    expect(out[0].source).toBe("WHOOP");
    expect(out[0].mean).toBe(51);
  });

  it("picks Withings over Apple for SpO₂", () => {
    const out = collapseRollupRowsBySource(
      [row(DAY1, "APPLE_HEALTH", 96), row(DAY1, "WITHINGS", 98)],
      "OXYGEN_SATURATION",
      null,
    );
    expect(out).toHaveLength(1);
    expect(out[0].source).toBe("WITHINGS");
    expect(out[0].mean).toBe(98);
  });

  it("picks native WHOOP over the COMPUTED proxy for RECOVERY_SCORE", () => {
    const out = collapseRollupRowsBySource(
      [row(DAY1, "COMPUTED", 62), row(DAY1, "WHOOP", 70)],
      "RECOVERY_SCORE",
      null,
    );
    expect(out).toHaveLength(1);
    expect(out[0].source).toBe("WHOOP");
  });

  it("collapses cumulative steps to ONE source's sum (never cross-source sum)", () => {
    const out = collapseRollupRowsBySource(
      [
        row(DAY1, "WITHINGS", 3800, 1, 3800),
        row(DAY1, "APPLE_HEALTH", 4000, 1, 4000),
      ],
      "ACTIVITY_STEPS",
      null,
    );
    expect(out).toHaveLength(1);
    // steps ladder = APPLE_HEALTH first → canonical source's sum only, NOT 7800.
    expect(out[0].source).toBe("APPLE_HEALTH");
    expect(out[0].sumValue).toBe(4000);
  });

  it("preserves multi-day series, collapsing each day independently", () => {
    const out = collapseRollupRowsBySource(
      [
        row(DAY1, "APPLE_HEALTH", 54),
        row(DAY1, "WHOOP", 51),
        row(DAY2, "WHOOP", 49),
      ],
      "RESTING_HEART_RATE",
      null,
    );
    expect(out).toHaveLength(2);
    expect(out.map((r) => r.bucketStart.getTime())).toEqual([
      DAY1.getTime(),
      DAY2.getTime(),
    ]);
    expect(out.every((r) => r.source === "WHOOP")).toBe(true);
  });

  it("leaves a single-source day unchanged (fast path)", () => {
    const input = [row(DAY1, "WITHINGS", 72)];
    const out = collapseRollupRowsBySource(input, "WEIGHT", null);
    expect(out).toBe(input);
  });

  it("honours a custom source-priority override", () => {
    // User pins Apple above WHOOP for resting heart rate.
    const custom = {
      restingHeartRate: ["APPLE_HEALTH", "WHOOP", "WITHINGS"],
    };
    const out = collapseRollupRowsBySource(
      [row(DAY1, "WHOOP", 51), row(DAY1, "APPLE_HEALTH", 54)],
      "RESTING_HEART_RATE",
      custom,
    );
    expect(out).toHaveLength(1);
    expect(out[0].source).toBe("APPLE_HEALTH");
  });

  it("falls back to the alphabetically-smallest source when none is on the ladder", () => {
    // Neither IMPORT nor MANUAL is on the restingHeartRate ladder; keep one
    // row deterministically by source name, matching the live-SQL paths'
    // `ORDER BY … source` tiebreak (live/rollup parity).
    const out = collapseRollupRowsBySource(
      [row(DAY1, "MANUAL", 58, 5), row(DAY1, "IMPORT", 60, 2)],
      "RESTING_HEART_RATE",
      null,
    );
    expect(out).toHaveLength(1);
    // "IMPORT" < "MANUAL" alphabetically.
    expect(out[0].source).toBe("IMPORT");
  });

  it("returns empty input untouched", () => {
    expect(collapseRollupRowsBySource([], "WEIGHT", null)).toEqual([]);
  });
});

src/lib/__tests__/crypto-bytes.test.ts.source:
import { describe, it, expect, beforeEach, vi } from "vitest";
import { Buffer } from "node:buffer";
import {
  encryptBytes,
  decryptBytes,
  extractKeyIdFromBytes,
  reencryptBytesToActive,
  encrypt,
  _resetCryptoCacheForTests,
} from "../crypto";

/**
 * The binary "binary2" codec: AES-256-GCM over raw bytes with a key-id
 * header, no base64 detour. Same versioned-key discipline as the string
 * codec — fail-closed on unknown versions, malformed headers, and
 * unconfigured key ids.
 */

const KEY_V1 =
  "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";
const KEY_V2 =
  "fedcba9876543210fedcba9876543210fedcba9876543210fedcba9876543210";

function useSingleKey() {
  vi.unstubAllEnvs();
  vi.stubEnv("ENCRYPTION_KEYS", "");
  vi.stubEnv("ENCRYPTION_ACTIVE_KEY_ID", "");
  vi.stubEnv("ENCRYPTION_KEY", KEY_V1);
  _resetCryptoCacheForTests();
}

function useKeyMap(active: "v1" | "v2") {
  vi.unstubAllEnvs();
  vi.stubEnv("ENCRYPTION_KEYS", JSON.stringify({ v1: KEY_V1, v2: KEY_V2 }));
  vi.stubEnv("ENCRYPTION_ACTIVE_KEY_ID", active);
  vi.stubEnv("ENCRYPTION_KEY", "");
  _resetCryptoCacheForTests();
}

describe("crypto binary codec (binary2)", () => {
  beforeEach(useSingleKey);

  it("round-trips raw binary payloads verbatim", () => {
    const payloads = [
      Buffer.alloc(0),
      Buffer.from([0x00, 0x01, 0xff, 0xfe]),
      Buffer.from("%PDF-1.7 with ünïcode and \u0000 NULs", "utf8"),
      Buffer.from(Array.from({ length: 100_000 }, (_, i) => i % 251)),
    ];
    for (const plain of payloads) {
      const encrypted = encryptBytes(plain);
      expect(encrypted.equals(plain)).toBe(false);
      expect(decryptBytes(encrypted).equals(plain)).toBe(true);
    }
  });

  it("writes the active key id into the header", () => {
    const payload = encryptBytes(Buffer.from("x"));
    expect(extractKeyIdFromBytes(payload)).toBe("v1");
  });

  it("costs a fixed small header, not the base64 +33 %", () => {
    const plain = Buffer.alloc(30_000, 7);
    const encrypted = encryptBytes(plain);
    // version(1) + idLen(1) + "v1"(2) + iv(12) + tag(16) = 32 bytes overhead.
    expect(encrypted.byteLength).toBe(plain.byteLength + 32);
  });

  it("decrypts rows written under an older configured key after rotation", () => {
    const plain = Buffer.from("clinical letter bytes");
    const oldPayload = encryptBytes(plain);
    useKeyMap("v2");
    // v1 is still in the map — decrypt succeeds; re-encrypt moves to v2.
    expect(decryptBytes(oldPayload).equals(plain)).toBe(true);
    const rotated = reencryptBytesToActive(oldPayload);
    expect(extractKeyIdFromBytes(rotated)).toBe("v2");
    expect(decryptBytes(rotated).equals(plain)).toBe(true);
  });

  it("fails closed on an unconfigured key id", () => {
    const payload = encryptBytes(Buffer.from("secret"));
    vi.stubEnv("ENCRYPTION_KEY", KEY_V2); // v1 material replaced
    _resetCryptoCacheForTests();
    // Header still says v1 but v1 now decodes to different key material →
    // GCM auth failure, never silent junk.
    expect(() => decryptBytes(payload)).toThrow();
  });

  it("fails closed on an unknown version byte", () => {
    const payload = encryptBytes(Buffer.from("secret"));
    const tampered = Buffer.from(payload);
    tampered[0] = 0x09;
    expect(() => decryptBytes(tampered)).toThrow(/version/i);
  });

  it("fails closed on truncated payloads", () => {
    const payload = encryptBytes(Buffer.from("secret"));
    expect(() => decryptBytes(payload.subarray(0, 1))).toThrow();
    expect(() => decryptBytes(payload.subarray(0, 10))).toThrow();
    expect(() => decryptBytes(Buffer.alloc(0))).toThrow();
  });

  it("fails closed on a tampered ciphertext (GCM auth)", () => {
    const payload = encryptBytes(Buffer.from("secret"));
    const tampered = Buffer.from(payload);
    tampered[tampered.byteLength - 1] ^= 0x01;
    expect(() => decryptBytes(tampered)).toThrow();
  });

  it("extractKeyIdFromBytes returns null for garbage instead of throwing", () => {
    expect(extractKeyIdFromBytes(Buffer.alloc(0))).toBeNull();
    expect(extractKeyIdFromBytes(Buffer.from([0x01, 0x02, 0x03]))).toBeNull();
    // A legacy string-codec payload (UTF-8 of an encrypt() string) is not a
    // binary2 header either.
    expect(
      extractKeyIdFromBytes(Buffer.from(encrypt("hello"), "utf8")),
    ).toBeNull();
  });
});

src/lib/analytics/__tests__/source-rank-.source:
/**
 * Unit pins for the source-rank SQL builders.
 *
 * `canonicalMeasurementsCte` (v1.18.11 perf#3a) was extracted so a statement
 * that references the canonical-source set more than once can bind it as a
 * single `WITH cm AS (…)` CTE and fold away the duplicate DISTINCT-ON
 * self-join. These tests pin:
 *   1. the alias-wrapped `canonicalMeasurementsFrom` is exactly the CTE body
 *      wrapped in `( … ) m` — so the single-reference call site is unchanged;
 *   2. the canonical body reads `measurements` once and picks with one window
 *      function, with no join for the planner to run as a nested loop — so a
 *      fold that references the CTE twice runs the pick once, and a table
 *      without statistics cannot turn it quadratic;
 *   3. the interval whitelist still rejects an unsafe splice;
 *   4. the window counts from an instant the caller took, never from the
 *      database clock.
 */
import { describe, expect, it } from "vitest";

import { boundInstantSql, instantLiteralSql } from "../request-clock-sql";
import {
  canonicalMeasurementsCte,
  canonicalMeasurementsFrom,
} from "../source-rank-sql";

const RANK = "90";
const NINETY_DAYS = { from: boundInstantSql(2), interval: "90 days" };

describe("canonicalMeasurementsCte / canonicalMeasurementsFrom", () => {
  it("wraps the CTE body verbatim in the ( … ) m alias", () => {
    const cte = canonicalMeasurementsCte(RANK, NINETY_DAYS);
    const from = canonicalMeasurementsFrom(RANK, NINETY_DAYS);
    // The alias form is the CTE body plus the closing `) m` wrapper. Pinning
    // equality means the single-reference call sites keep byte-stable SQL
    // while the CTE body can be reused for the folded double-reference case.
    expect(from).toBe(`(${cte}\n      ) m`);
  });

  it("picks with one window over one scan, with no join", () => {
    const cte = canonicalMeasurementsCte(RANK, NINETY_DAYS);
    expect(cte.match(/FROM measurements\b/g) ?? []).toHaveLength(1);
    expect(cte.match(/FIRST_VALUE\(/g) ?? []).toHaveLength(1);
    expect(cte).not.toMatch(/\bJOIN\b|DISTINCT ON/);
  });

  it("binds the user id as $1 and scopes the scan to the window", () => {
    const cte = canonicalMeasurementsCte(RANK, NINETY_DAYS);
    // user id is always a bound parameter, never spliced.
    expect(cte).toContain('"user_id" = $1');
    // The trailing-window bound scopes the one scan, so the pick and the rows
    // it keeps are cut by the same window.
    const intervalMatches =
      cte.match(/>= \$2::timestamp - INTERVAL '90 days'/g) ?? [];
    expect(intervalMatches).toHaveLength(1);
  });

  it("never cuts its window on the database clock", () => {
    for (const cte of [
      canonicalMeasurementsCte(RANK, NINETY_DAYS),
      canonicalMeasurementsCte(RANK, { from: boundInstantSql(3) }),
      canonicalMeasurementsCte(RANK, {
        from: instantLiteralSql(new Date("2026-03-01T06:30:00.000Z")),
        interval: "1 day",
      }),
    ]) {
      expect(cte).not.toMatch(/NOW\(\)|CURRENT_|LOCALTIMESTAMP/i);
    }
    expect(
      canonicalMeasurementsCte(RANK, {
        from: instantLiteralSql(new Date("2026-03-01T06:30:00.000Z")),
        interval: "1 day",
      }),
    ).toContain(`>= '2026-03-01 06:30:00.000'::timestamp - INTERVAL '1 day'`);
  });

  it("omits the window clause entirely when no interval is given", () => {
    const cte = canonicalMeasurementsCte(RANK);
    expect(cte).not.toContain("INTERVAL");
  });

  it("rejects an unsafe interval splice", () => {
    expect(() =>
      canonicalMeasurementsCte(RANK, {
        from: boundInstantSql(2),
        interval: "90 days; DROP TABLE",
      }),
    ).toThrow(/unsafe interval/);
  });

  it("rejects an instant that is neither a bound parameter nor a literal it wrote", () => {
    for (const from of [
      "NOW()",
      "$2",
      "'2026-03-01'::timestamp",
      "$2::timestamp; DROP TABLE",
    ]) {
      expect(() =>
        canonicalMeasurementsCte(RANK, { from, interval: "90 days" }),
      ).toThrow(/unsafe instant/);
    }
  });
});

src/lib/analytics/compliance/__tests__/p.source:
/**
 * #1028 — slots before a medication's creation, on the compliance side.
 *
 * The dose-history ledger keeps a slot that predates the medication only
 * when a recorded dose claims it. Every adherence surface tallies that same
 * ledger, so the rate, the per-window counts and the heatmap must agree with
 * the history view: the creation day's 14:00 dose, recorded afterwards on its
 * own slot, counts as taken on time, and the 09:00 slot before the medication
 * existed (holding only the projector's auto-missed placeholder) counts as
 * nothing. A caller whose window starts before the creation (the doctor
 * report, the Coach) must not read the pre-existence slots as missed either.
 */
import { describe, expect, it } from "vitest";

import {
  buildMedicationComplianceBundle,
  tallyComplianceFromLedger,
  type ComplianceMedicationContext,
  type ComplianceSchedule,
  type IntakeEvent,
} from "@/lib/analytics/compliance";
import { localHmAsUtc } from "@/lib/tz/local-day";
import { userDayKey } from "@/lib/tz/resolver";

const DAY_MS = 24 * 60 * 60 * 1000;

const schedule: ComplianceSchedule = {
  windowStart: "09:00",
  windowEnd: "09:00",
  timesOfDay: ["09:00", "14:00", "21:00"],
  daysOfWeek: null,
  rrule: null,
  rollingIntervalDays: null,
  reminderGraceMinutes: null,
  scheduleType: "SCHEDULED",
  cyclicOnWeeks: null,
  cyclicOffWeeks: null,
};

for (const tz of ["Asia/Kolkata", "America/New_York"]) {
  describe(`compliance over a medication added mid-day (#1028, ${tz})`, () => {
    const day1 = new Date("2026-09-23T12:00:00Z");
    const day2 = new Date("2026-09-24T12:00:00Z");
    const d1 = (h: number, m = 0) => localHmAsUtc(day1, tz, h, m);
    const d2 = (h: number, m = 0) => localHmAsUtc(day2, tz, h, m);
    const createdAt = d1(16, 5);
    const now = d2(22, 0);

    const ctx: ComplianceMedicationContext = {
      startsOn: new Date("2026-09-23T00:00:00Z"),
      endsOn: new Date("2026-09-28T00:00:00Z"),
      endedAt: null,
      oneShot: false,
      createdAt,
      lastIntakeAt: d2(21, 30),
      timeZone: tz,
    };
    const take = (slot: Date, takenAt: Date): IntakeEvent => ({
      scheduledFor: slot,
      takenAt,
      skipped: false,
      autoMissed: false,
    });
    const events: IntakeEvent[] = [
      { scheduledFor: d1(9), takenAt: null, skipped: false, autoMissed: true },
      take(d1(14), d1(14)),
      take(d1(21), d1(21)),
      take(d2(9), d2(10)),
      take(d2(14), d2(14)),
      take(d2(21), d2(21, 30)),
    ];

    it("counts the recorded pre-creation dose and ignores the placeholder", () => {
      const bundle = buildMedicationComplianceBundle(
        events,
        [schedule],
        ctx,
        now,
      );
      expect(bundle.compliance7).toMatchObject({
        taken: 5,
        missed: 0,
        skipped: 0,
        rate: 100,
      });
      const creationDay = bundle.ledgerRows.filter(
        (r) => userDayKey(r.at, tz) === userDayKey(d1(12), tz),
      );
      expect(creationDay.map((r) => [r.kind, r.timeOfDay, r.status])).toEqual([
        ["slot", "14:00", "taken_on_time"],
        ["slot", "21:00", "taken_on_time"],
      ]);
    });

    it("never reads pre-existence slots as missed in a wider window", () => {
      // The doctor report and the Coach tally a window that starts before
      // the medication existed.
      const tally = tallyComplianceFromLedger(
        [],
        [schedule],
        { ...ctx, lastIntakeAt: null },
        new Date(now.getTime() - 30 * DAY_MS),
        d2(3, 0),
        d2(3, 0),
      );
      // Only the creation day's 21:00 slot was expected, and never taken.
      expect(tally).toMatchObject({ taken: 0, missed: 1, denominator: 1 });
    });
  });
}

src/lib/analytics/compliance/__tests__/c.source:
/**
 * #1280 — a course ended at an instant expects no dose after it, in the
 * streak and the per-window timeline as in the rate.
 *
 * The person lives in Europe/Berlin and doses at 08:00 and 20:00 local
 * (06:00Z and 18:00Z in October before the clock change). Every dose of the
 * last twenty days was taken, except the evening one on the day the course
 * was ended at noon: that slot came after the end and was never due.
 */
import { describe, expect, it } from "vitest";

import {
  buildMedicationComplianceBundle,
  calculateCompliance,
} from "@/lib/analytics/compliance/display";
import {
  buildComplianceMedicationContext,
  type ComplianceSchedule,
} from "@/lib/analytics/compliance/types";

const TZ = "Europe/Berlin";
const DAY = 86_400_000;
const NOW = new Date("2026-10-25T10:00:00.000Z");
const ENDED_AT = new Date("2026-10-24T10:00:00.000Z");
const CREATED_AT = new Date(NOW.getTime() - 20 * DAY);

const schedules: ComplianceSchedule[] = [
  {
    windowStart: "08:00",
    windowEnd: "09:00",
    timesOfDay: ["08:00", "20:00"],
    daysOfWeek: null,
    rrule: null,
    rollingIntervalDays: null,
    reminderGraceMinutes: null,
    scheduleType: "SCHEDULED",
    cyclicOnWeeks: null,
    cyclicOffWeeks: null,
  },
];

/** Every dose taken on time; the end day's evening only when asked. */
function events(withLastEvening: boolean) {
  const out: Array<{
    scheduledFor: Date;
    takenAt: Date;
    skipped: boolean;
    autoMissed: boolean;
  }> = [];
  for (let d = 19; d >= 0; d -= 1) {
    const key = new Date(Date.UTC(2026, 9, 24 - d)).toISOString().slice(0, 10);
    const morning = new Date(`${key}T06:00:00.000Z`);
    out.push({
      scheduledFor: morning,
      takenAt: morning,
      skipped: false,
      autoMissed: false,
    });
    if (d > 0 || withLastEvening) {
      const evening = new Date(`${key}T18:00:00.000Z`);
      out.push({
        scheduledFor: evening,
        takenAt: evening,
        skipped: false,
        autoMissed: false,
      });
    }
  }
  return out;
}

function context(endedAt: Date | null) {
  return buildComplianceMedicationContext(
    {
      startsOn: new Date(Date.UTC(2026, 9, 4)),
      endsOn: new Date(Date.UTC(2026, 9, 24)),
      endedAt,
      oneShot: false,
      createdAt: CREATED_AT,
    },
    new Date("2026-10-24T06:00:00.000Z"),
    TZ,
  );
}

describe("a course ended at an instant", () => {
  it("does not break the streak on the slot after the end", () => {
    const ended = calculateCompliance(events(false), schedules, 7, CREATED_AT, {
      now: NOW,
      medicationContext: context(ENDED_AT),
    });
    // The same course run to the end of its last day with every dose taken.
    const whole = calculateCompliance(events(true), schedules, 7, CREATED_AT, {
      now: NOW,
      medicationContext: context(null),
    });
    expect(whole.streak).toBeGreaterThan(0);
    expect(ended.missed).toBe(0);
    expect(ended.streak).toBe(whole.streak);
  });

  it("does not break the bundle's streaks either", () => {
    const ended = buildMedicationComplianceBundle(
      events(false),
      schedules,
      context(ENDED_AT),
      NOW,
    );
    const whole = buildMedicationComplianceBundle(
      events(true),
      schedules,
      context(null),
      NOW,
    );
    expect(whole.compliance7.streak).toBeGreaterThan(0);
    expect(ended.compliance7.missed).toBe(0);
    expect(ended.compliance7.streak).toBe(whole.compliance7.streak);
    expect(ended.compliance30.streak).toBe(whole.compliance30.streak);
  });
});

src/lib/rollups/__tests__/measurement-re.source:
/**
 * v1.5.0 — unit tests for the rollup-read aggregation helpers.
 *
 * Pins the `count` / `min` / `max` / `mean` re-aggregation across
 * DAY buckets — the linearly-composable subset of the
 * comprehensive-aggregator's `DataSummary` shape that survives
 * round-tripping through the rollup table.
 */
import { describe, expect, it } from "vitest";

import { aggregateBuckets, type DailyMeanRow } from "../measurement-read";

const dayA: DailyMeanRow = {
  day: new Date("2026-05-08T00:00:00.000Z"),
  count: 2,
  mean: 80,
  minValue: 79,
  maxValue: 81,
};
const dayB: DailyMeanRow = {
  day: new Date("2026-05-09T00:00:00.000Z"),
  count: 3,
  mean: 82,
  minValue: 80,
  maxValue: 84,
};
const dayC: DailyMeanRow = {
  day: new Date("2026-05-10T00:00:00.000Z"),
  count: 5,
  mean: 83,
  minValue: 81,
  maxValue: 86,
};

describe("aggregateBuckets", () => {
  it("returns the empty-window shape when given no rows", () => {
    expect(aggregateBuckets([])).toEqual({
      count: 0,
      min: null,
      max: null,
      mean: null,
    });
  });

  it("sums count and folds min / max across days", () => {
    const result = aggregateBuckets([dayA, dayB, dayC]);
    expect(result.count).toBe(10);
    expect(result.min).toBe(79);
    expect(result.max).toBe(86);
  });

  it("weighs the mean by daily count (not equal-weight)", () => {
    const result = aggregateBuckets([dayA, dayB, dayC]);
    // Σ(count × mean) / Σcount = (2×80 + 3×82 + 5×83) / 10
    //                          = (160 + 246 + 415) / 10
    //                          = 82.1
    expect(result.mean).toBeCloseTo(82.1, 5);
  });

  it("handles a single bucket without arithmetic drift", () => {
    const result = aggregateBuckets([dayB]);
    expect(result.count).toBe(3);
    expect(result.min).toBe(80);
    expect(result.max).toBe(84);
    expect(result.mean).toBe(82);
  });
});

describe("aggregateBuckets, one weight per day", () => {
  // A workout day (many readings) and a rest day (few). By readings the window
  // mean is dominated by the workout day; with one weight per day it is the
  // mean of the two days' means.
  const workout: DailyMeanRow = {
    day: new Date("2026-05-08T00:00:00.000Z"),
    count: 900,
    mean: 64,
    minValue: 60,
    maxValue: 150,
  };
  const rest: DailyMeanRow = {
    day: new Date("2026-05-09T00:00:00.000Z"),
    count: 100,
    mean: 56,
    minValue: 50,
    maxValue: 70,
  };

  it("weighs a day by its readings by default", () => {
    const result = aggregateBuckets([workout, rest]);
    expect(result.mean).toBeCloseTo((900 * 64 + 100 * 56) / 1000, 9);
  });

  it("weighs every day once when asked, and still counts every reading", () => {
    const result = aggregateBuckets([workout, rest], "day");
    expect(result.mean).toBeCloseTo((64 + 56) / 2, 9);
    expect(result.count).toBe(1000);
    expect(result.min).toBe(50);
    expect(result.max).toBe(150);
  });

  it("gives a day with no readings no weight under either rule", () => {
    const empty: DailyMeanRow = { ...rest, count: 0, mean: 999 };
    expect(aggregateBuckets([workout, empty], "day").mean).toBe(64);
    expect(aggregateBuckets([empty], "day")).toEqual({
      count: 0,
      min: null,
      max: null,
      mean: null,
    });
  });
});

src/lib/rollups/__tests__/coverage-infli.source:
import { beforeEach, describe, expect, it, vi } from "vitest";

const { queryRaw } = vi.hoisted(() => ({ queryRaw: vi.fn() }));
vi.mock("@/lib/db", () => ({ prisma: { $queryRaw: queryRaw } }));

import { invalidateUserMeasurements } from "@/lib/cache/invalidate";
import { probeRollupCoverage } from "../measurement-coverage";

function deferred<T>() {
  let resolve!: (value: T) => void;
  let reject!: (err: unknown) => void;
  const promise = new Promise<T>((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

beforeEach(() => {
  queryRaw.mockReset();
});

describe("probeRollupCoverage single-flight", () => {
  it("shares one query between concurrent probes of an account", async () => {
    const rows = deferred<Array<{ type: string; has_buckets: boolean }>>();
    queryRaw.mockReturnValueOnce(rows.promise);

    const a = probeRollupCoverage("u1");
    const b = probeRollupCoverage("u1");
    rows.resolve([
      { type: "PULSE", has_buckets: true },
      { type: "WEIGHT", has_buckets: false },
    ]);
    const [ma, mb] = await Promise.all([a, b]);

    expect(queryRaw).toHaveBeenCalledTimes(1);
    expect(Object.fromEntries(ma)).toEqual({ PULSE: true, WEIGHT: false });
    expect(mb).toEqual(ma);
    // Each caller owns its map.
    expect(mb).not.toBe(ma);
    ma.set("PULSE", false);
    expect(mb.get("PULSE")).toBe(true);
  });

  it("keeps nothing once the query settles, and never joins across accounts", async () => {
    queryRaw.mockResolvedValue([{ type: "PULSE", has_buckets: true }]);
    await probeRollupCoverage("u1");
    await probeRollupCoverage("u1");
    await Promise.all([probeRollupCoverage("u1"), probeRollupCoverage("u2")]);
    expect(queryRaw).toHaveBeenCalledTimes(4);
  });

  it("starts afresh after a measurement write", async () => {
    const first = deferred<Array<{ type: string; has_buckets: boolean }>>();
    queryRaw
      .mockReturnValueOnce(first.promise)
      .mockResolvedValueOnce([{ type: "WEIGHT", has_buckets: false }]);

    const before = probeRollupCoverage("u1");
    invalidateUserMeasurements("u1");
    const after = probeRollupCoverage("u1");
    first.resolve([]);

    expect((await before).size).toBe(0);
    expect(Object.fromEntries(await after)).toEqual({ WEIGHT: false });
    expect(queryRaw).toHaveBeenCalledTimes(2);
  });

  it("passes a failure to every joined caller and does not keep it", async () => {
    const failing = deferred<Array<{ type: string; has_buckets: boolean }>>();
    queryRaw
      .mockReturnValueOnce(failing.promise)
      .mockResolvedValueOnce([{ type: "PULSE", has_buckets: true }]);

    const a = probeRollupCoverage("u1");
    const b = probeRollupCoverage("u1");
    failing.reject(new Error("db down"));
    await expect(a).rejects.toThrow("db down");
    await expect(b).rejects.toThrow("db down");

    expect((await probeRollupCoverage("u1")).get("PULSE")).toBe(true);
  });
});

